export const assessmentQuestions=Object.values(bank).flatMap(b=>[...b.pre,...b.post]);
export function sameAnswers(a,b){return Array.isArray(a)&&a.length===b.length&&[...a].sort((x,y)=>x-y).every((v,i)=>v===[...b].sort((x,y)=>x-y)[i]);}
export function evaluatePretest(lessonId,answers={},uncertain={}){
 const list=bank[lessonId].pre;
 const correct=list.filter(q=>sameAnswers(answers[q.id]||[],q.correct));
 const core=list.filter(q=>q.core),coreCorrect=core.filter(q=>sameAnswers(answers[q.id]||[],q.correct));
 const needs=list.filter(q=>!sameAnswers(answers[q.id]||[],q.correct)||uncertain[q.id]);
 return {score:correct.length,total:list.length,coreScore:coreCorrect.length,coreTotal:core.length,passed:correct.length>=4&&coreCorrect.length===core.length,reviewSteps:[...new Set(needs.flatMap(q=>q.reviewSteps))].sort((a,b)=>a-b),wrongIds:list.filter(q=>!sameAnswers(answers[q.id]||[],q.correct)).map(q=>q.id),uncertainIds:list.filter(q=>uncertain[q.id]).map(q=>q.id)};
}
